<template><AppShell><view class="detail-crumb"><button class="text-button" @tap="back">‹ 返回名单</button><button class="text-button" @tap="go('statistics')">收录说明</button></view><template v-if="person"><view class="registry-cover"><image src="/static/landscape.svg" mode="aspectFill"/><view><text class="eyebrow">人物资料条目 / RECORD</text><text class="page-title">{{person.name}}</text><text class="tag">资料包记录 · 待独立复核</text></view></view><view class="identity-grid"><view><text>出生日期</text><text>{{person.birthText|| (person.birthYear?person.birthYear+'年':'未载')}}</text></view><view><text>籍贯原文</text><text>{{person.originText||'未载'}}</text></view><view><text>出生地</text><text>{{person.birthplace||'未载，不从籍贯推导'}}</text></view></view><view v-if="person.supplementStatus||person.supplementNotes?.length||person.scopeNote" class="fact-card"><text class="section-title">补充资料说明</text><text v-if="person.supplementStatus" class="small">{{person.supplementStatus}}</text><text v-if="person.ancestryText" class="reading-body">祖籍：{{person.ancestryText}}（与本人籍贯分别记录）</text><text v-if="person.birthConflict" class="tag">出生日期有另载 · 尚未定论</text><text v-if="person.scopeNote" class="reading-body">{{person.scopeNote}}</text><text v-for="(note,i) in person.supplementNotes" :key="i" class="small">{{note}}</text><text v-if="person.birthSourceUrl" class="small" selectable>出生日期补充来源：{{person.birthSourceUrl}}</text><text v-for="u in person.supplementUrls" :key="u" class="small" selectable>回填来源线索：{{u}}</text></view><view class="fact-card"><text class="section-title">资料与依据</text><text class="small">来源类别：{{person.memberships?.join(' · ')}}</text><text class="small">地区依据：{{person.regionBasis}}</text><text v-if="person.regionEvidence" class="small">地域摘录：{{person.regionEvidence.excerpt}} · {{person.regionEvidence.location}}</text><text class="reading-body">{{person.contribution||'本条仅用于姓名收录，详细生平尚未展开。'}}</text><text class="small">{{person.sourceLabel || (person.sourceId ? '来源线索：'+person.sourceId : '来源待补充')}}</text><text class="small">来源线索不等于已经核到名录原件；正式统计仍需独立复核。</text><view v-if="url" class="source-url"><text selectable>{{url}}</text><button class="outline" @tap="copy">复制来源链接</button><!-- #ifdef H5 --><a :href="url" target="_blank" rel="noopener noreferrer" class="text-button">打开来源 ↗</a><!-- #endif --></view><text v-else class="muted">当前条目没有直接来源网址，暂保留资料线索，待补充。</text></view><view v-if="person.readingId" class="next-actions"><button class="primary" @tap="go('person',{id:person.readingId})">展开人物档案 ↗</button></view><view class="next-actions"><button class="outline" @tap="go('people')">浏览深度人物档案</button><button class="outline" @tap="go('assistant')">打开小迹导览</button></view></template><StatePanel v-else title="未找到该资料条目" message="请返回名单重新选择。"/></AppShell></template>
<script setup>
import {ref,computed,onMounted,onBeforeUnmount} from 'vue';import {onLoad,onShow} from '@dcloudio/uni-app';import AppShell from '../../components/AppShell.vue';import StatePanel from '../../components/StatePanel.vue';import {allRecords as people} from '../../lib/全国收录.js';import {go} from '../../lib/navigation.js'
const person=ref(null),url=computed(()=>{const u=person.value?.regionEvidence?.url||person.value?.sourceEvidence?.url||person.value?.detailUrl||'';return /^https?:\/\//.test(u)?u:''})
function loadRecord(id){person.value=people.find(p=>p.id===id||p.rawIds?.includes(id))||null}
onLoad(o=>loadRecord(o.id))
// #ifdef H5
function syncRecord(){if(!location.hash.includes('/pages/registry/index'))return;loadRecord(new URLSearchParams(location.hash.split('?')[1]||'').get('id'))}
onMounted(()=>window.addEventListener('hashchange',syncRecord));onBeforeUnmount(()=>window.removeEventListener('hashchange',syncRecord));onShow(syncRecord)
// #endif
function back(){if(getCurrentPages().length>1)uni.navigateBack();else go('province',{code:person.value?.provinceCode||''})}
function copy(){uni.setClipboardData({data:url.value})}
</script>
